-- 2. ARTICULOS INSTITUCIONALES TEINCO
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Admisiones y Mercadeo', 'Inscripciones y Requisitos', 'Requisitos de Inscripción para Estudiantes Nuevos en TEINCO', 'Para inscribirte a los programas tecnológicos y profesionales de TEINCO requieres: 1) Formulario de inscripción diligenciado en la página oficial. 2) Fotocopia legible del documento de identidad (C.C. o T.I.). 3) Fotocopia del diploma de bachiller o acta de grado original. 4) Resultado de las pruebas de Estado Saber 11 (ICFES). 5) Certificado de afiliación a EPS o SISBÉN vigente. 6) 1 fotografía tamaño 3x4 fondo blanco reciente. Una vez cargados los documentos, admisiones te agendará la entrevista vocacional.', 'inscripcion, requisitos, matricularse, nuevo ingreso, icfes, bachiller, saber 11, documentos', 'admisiones@teinco.edu.co', '+57 601 7433200', 'Sede Principal Calle 57 No. 9-28', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Admisiones y Mercadeo', 'Oferta Académica', 'Programas Académicos y Carreras por Ciclos Propedéuticos en TEINCO', 'La oferta académica de TEINCO está organizada en 3 Facultades mediante ciclos propedéuticos que te permiten titularte como Técnico Profesional, Tecnólogo y Profesional/Ingeniero: 1) Facultad de Ingeniería y Tecnologías: Ingeniería de Sistemas (Técnica en Programación de Computadores, Tecnología en Desarrollo de Software, Ingeniería de Sistemas) e Ingeniería Mecatrónica (Técnica en Mantenimiento Mecatrónico, Tecnología en Automatización Industrial, Ingeniería Mecatrónica). 2) Facultad de Ciencias Económicas y Administrativas: Administración de Empresas (Técnica en Procesos Administrativos, Tecnología en Gestión Empresarial, Administración de Empresas) y Contaduría Pública (Técnica en Procesos Contables, Tecnología en Gestión Contable y Tributaria, Contaduría Pública). 3) Facultad de Diseño y Comunicación Digital: Profesional en Diseño Digital Publicitario (Técnica en Producción Gráfica, Tecnología en Proyectos Publicitarios, Diseño Digital) y Profesional en Marketing y Negocios Digitales (Técnica en Estrategias Comerciales, Tecnología en Gestión de Mercadeo, Marketing y Negocios Digitales).', 'carreras, programas, ingenieria de sistemas, mecatronica, administracion de empresas, contaduria publica, diseno digital publicitario, marketing y negocios digitales, facultades, ciclos propedeuticos, que carreras hay', 'admisiones@teinco.edu.co', '+57 601 7433200', 'Sede Principal Calle 57 No. 9-28', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m. | Sábados: 7:00 a.m. a 4:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Admisiones y Mercadeo', 'Oferta Académica', 'Facultad de Ingeniería y Tecnologías TEINCO', 'La Facultad de Ingeniería y Tecnologías de TEINCO ofrece programas por ciclos propedéuticos: 1) Ingeniería de Sistemas: Ciclo Técnico en Programación de Computadores, Ciclo Tecnológico en Desarrollo de Software y Sistemas de Información, y Ciclo Profesional en Ingeniería de Sistemas. 2) Ingeniería Mecatrónica: Ciclo Técnico en Mantenimiento de Sistemas Mecatrónicos, Ciclo Tecnológico en Automatización de Procesos Industriales, y Ciclo Profesional en Ingeniería Mecatrónica. Dispone de laboratorios de robótica, electrónica y salas de cómputo especializadas.', 'ingenieria, ingenieria de sistemas, mecatronica, automatizacion, programacion, computadores, tecnologia en software', 'admisiones@teinco.edu.co', '+57 601 7433200', 'Sede Principal Calle 57 No. 9-28', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Admisiones y Mercadeo', 'Oferta Académica', 'Facultad de Ciencias Económicas y Administrativas TEINCO', 'La Facultad de Ciencias Económicas y Administrativas de TEINCO forma líderes empresariales y financieros: 1) Administración de Empresas: Ciclo Técnico en Procesos Administrativos, Ciclo Tecnológico en Gestión Empresarial, y Ciclo Profesional en Administración de Empresas. 2) Contaduría Pública: Ciclo Técnico en Procesos Contables y Financieros, Ciclo Tecnológico en Gestión Contable y Tributaria, y Ciclo Profesional en Contaduría Pública. Enfoque en alta gerencia, finanzas corporativas, emprendimiento y estándares internacionales NIIF.', 'administracion, empresas, contaduria, contable, tributaria, finanzas, economia, gestion empresarial', 'admisiones@teinco.edu.co', '+57 601 7433200', 'Sede Principal Calle 57 No. 9-28', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Admisiones y Mercadeo', 'Oferta Académica', 'Facultad de Diseño y Comunicación Digital TEINCO', 'La Facultad de Diseño y Comunicación Digital lidera la creatividad publicitaria y el comercio electrónico: 1) Profesional en Diseño Digital Publicitario: Ciclo Técnico en Producción Gráfica Digital, Ciclo Tecnológico en Gestión de Proyectos Digitales Publicitarios, y Ciclo Profesional en Diseño Digital Publicitario. 2) Profesional en Marketing y Negocios Digitales: Ciclo Técnico en Ejecución de Estrategias Comerciales, Ciclo Tecnológico en Gestión de Mercadeo Digital, y Ciclo Profesional en Marketing y Negocios Digitales. Abarca branding, animación, redes sociales, e-commerce, pauta y analítica de audiencias.', 'diseno, diseno digital, publicidad, marketing, mercadeo digital, negocios digitales, diseno publicitario, produccion grafica', 'admisiones@teinco.edu.co', '+57 601 7433200', 'Sede Principal Calle 57 No. 9-28', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Admisiones y Mercadeo', 'Homologaciones', 'Transferencias Externas y Homologación de Asignaturas', 'Si vienes de otra universidad o del SENA, puedes solicitar homologación de materias. Debes radicar en admisiones: 1) Certificado oficial de calificaciones de la institución de procedencia. 2) Contenidos programáticos (sílabos) debidamente sellados. 3) Certificado de buena conducta. El comité curricular evaluará las materias cursadas con nota mínima de 3.5 y afinidad de contenido del 80%.', 'homologacion, homologar, sena, transferencia, cambio de universidad, convalidar materias', 'admisiones@teinco.edu.co', '+57 601 7433200', 'Sede Principal Calle 57 No. 9-28', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Registro y Control', 'Certificados y Constancias', 'Expedición de Certificados de Estudio y Calificaciones', 'Para solicitar un certificado de notas, constancia de estudio, terminación de materias o conducta: 1) Descarga la orden de pago o solicítala a Cartera y cancela los derechos mediante PSE o en bancos. 2) Envía el soporte de pago al correo coordinacionregistroycontrol@teinco.edu.co indicando: Nombre completo, número de documento, programa académico y tipo de certificado. El tiempo oficial de expedición es de 3 a 5 días hábiles con firma digital reglamentaria o retiro presencial en ventanilla.', 'certificado, notas, constancia de estudio, certificado de conducta, contenidos programmaticos, expedicion', 'coordinacionregistroycontrol@teinco.edu.co', '+57 601 7433200 | WhatsApp: 301 333 7956', 'Sede Principal Calle 57 No. 9-28 / Sede Caracas Av. Caracas No. 57-41', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m. | Sábados: 7:00 a.m. a 4:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Registro y Control', 'Matrícula y Horarios', 'Proceso de Matrícula Académica y Asignación de Horarios', 'La matrícula consta de dos fases obligatorias: 1) Matrícula Financiera: Pago del valor del semestre en fechas ordinarias o extraordinarias. 2) Matrícula Académica: Inscripción de asignaturas en el portal Q10. Los estudiantes pueden realizar adición o retiro de asignaturas durante las dos primeras semanas de clases del calendario académico oficial.', 'matricula academica, inscribir materias, horarios, semestres, carga academica, q10', 'coordinacionregistroycontrol@teinco.edu.co', '+57 601 7433200 | WhatsApp: 301 333 7956', 'Sede Principal Calle 57 No. 9-28 / Sede Caracas Av. Caracas No. 57-41', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m. | Sábados: 7:00 a.m. a 4:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Registro y Control', 'Grados y Titulación', 'Requisitos para Grado y Ceremonia de Titulación en TEINCO', 'Para postularse a grado en TEINCO debes: 1) Aprobar el 100% de los créditos de la malla curricular. 2) Aprobar la opción de grado elegida (Proyecto de Software, Monografía, Seminario). 3) Certificar el nivel de inglés exigido institucionalmente. 4) Presentar la prueba de Estado Saber TyT / Saber Pro. 5) Obtener el Paz y Salvo general (Biblioteca, Cartera, Coordinación, Bienestar). 6) Cancelar los derechos de grado dentro de las fechas fijadas por Secretaría General.', 'grado, ceremonia de grado, paz y salvo, saber pro, saber tyt, derechos de grado, titulacion', 'coordinacionregistroycontrol@teinco.edu.co', '+57 601 7433200 | WhatsApp: 301 333 7956', 'Sede Principal Calle 57 No. 9-28 / Sede Caracas Av. Caracas No. 57-41', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m. | Sábados: 7:00 a.m. a 4:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Bienestar Institucional', 'Salud y Psicología', 'Acompañamiento Psicológico, Orientación y Salud Integral', 'Bienestar ofrece atención gratuita y confidencial: • Orientación y consulta psicológica para manejo de estrés, ansiedad y orientación vocacional. • Primeros auxilios y enfermería institucional en la sede principal. • Programa de acompañamiento y permanencia estudiantil (PAE) para estudiantes en condición de prueba académica. Para agendar tu cita, escribe a bienestar@teinco.edu.co o acércate al piso 3.', 'psicologia, cita psicologica, salud, enfermeria, estres, orientacion emocional, permanencia', 'bienestar@teinco.edu.co', '+57 601 7433200', 'Sede Principal Calle 57 No. 9-28, Piso 3', 'Lunes a Viernes: 8:00 a.m. a 6:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Bienestar Institucional', 'Cultura y Deportes', 'Actividades Culturales y Selecciones Deportivas TEINCO', 'Bienestar promueve la formación integral extracurricular: • Deportes: Fútbol de Salón (Masculino y Femenino), Voleibol, Baloncesto, Tenis de Mesa y Ajedrez. • Cultura: Danza moderna y folclórica, Ensamble Musical, Teatro y Fotografía. La participación en selecciones institucionales otorga puntos para beneficios de becas.', 'deportes, futbol, voleibol, musica, danza, teatro, ajedrez, torneos, gimnasio, actividades', 'bienestar@teinco.edu.co', '+57 601 7433200', 'Sede Principal Calle 57 No. 9-28, Piso 3', 'Lunes a Viernes: 8:00 a.m. a 6:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Bienestar Institucional', 'Becas y Auxilios', 'Becas por Rendimiento Académico y Auxilios Socioeconómicos', 'TEINCO premia el esfuerzo de sus estudiantes: 1) Beca de Excelencia: Exención de matrícula para el promedio ponderado más alto del programa (mínimo 4.5). 2) Beca Monitoría: Para estudiantes destacados que apoyan laboratorios, salas de software o tutorías académicas. 3) Descuento por Hermanos: 10% de descuento cuando dos familiares directos estudian en TEINCO. Las convocatorias se abren al cierre de cada semestre lectivo.', 'becas, descuentos, monitorias, convenio familiar, promedio, auxilio economico, gratuidad', 'bienestar@teinco.edu.co', '+57 601 7433200', 'Sede Principal Calle 57 No. 9-28, Piso 3', 'Lunes a Viernes: 8:00 a.m. a 6:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Cartera y Financiación', 'Medios de Pago', 'Medios de Pago Autorizados y Generación de Recibos', 'Puedes cancelar matrículas y derechos pecuniarios a través de: 1) Botón PSE en línea desde la página oficial de TEINCO. 2) Consignación bancaria en Bancolombia o Banco Davivienda usando el código de convenio institucional. 3) Caja institucional en la sede principal con tarjeta débito, crédito o efectivo. Para legalizar pagos en bancos, la referencia se valida en el sistema en 24 horas hábiles.', 'pse, pago matricula, bancos, consignacion, davivienda, bancolombia, recibo de pago, factura', 'cartera@teinco.edu.co', '+57 601 7433200 Ext. 104 - 105', 'Sede Principal Calle 57 No. 9-28, Mezanine', 'Lunes a Viernes: 7:00 a.m. a 8:00 p.m. | Sábados: 8:00 a.m. a 1:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Cartera y Financiación', 'Financiación y Créditos', 'Opciones de Financiación, Crédito Directo e ICETEX', 'TEINCO te ofrece alternativas para financiar tu matrícula: • Crédito Directo TEINCO: Cuota inicial del 40% y el saldo en cuotas mensuales durante el semestre académico sin trámites bancarios complejos. • ICETEX: Líneas Tú Eliges (0%, 25%, 100%) y subsidios de sostenimiento. • Convenios Financieros: Fincomercio, Banco Pichincha, Sufi Bancolombia y Coopecrédito con tasas preferenciales.', 'icetex, cuotas, credito directo, financiacion, cuota inicial, fincomercio, pichincha, pagar a plazos', 'cartera@teinco.edu.co', '+57 601 7433200 Ext. 104 - 105', 'Sede Principal Calle 57 No. 9-28, Mezanine', 'Lunes a Viernes: 7:00 a.m. a 8:00 p.m. | Sábados: 8:00 a.m. a 1:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Cartera y Financiación', 'Paz y Salvo', 'Expedición de Paz y Salvo Financiero', 'El Paz y Salvo Financiero certifica que te encuentras al día en todas tus obligaciones pecuniarias. Es indispensable para solicitar certificados de estudio, renovar matrícula semestral y para postulación a grados. Si estás al día con tus pagos, se genera en línea o solicitándolo al correo cartera@teinco.edu.co en 24 a 48 horas hábiles.', 'paz y salvo financiero, deuda, saldo pendiente, estado de cuenta, factura al dia', 'cartera@teinco.edu.co', '+57 601 7433200 Ext. 104', 'Sede Principal Calle 57 No. 9-28, Mezanine', 'Lunes a Viernes: 7:00 a.m. a 8:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Coordinación Académica', 'Prácticas Profesionales', 'Reglamento y Requisitos de Prácticas Profesionales en Software', 'Para iniciar tu Práctica Profesional en la Tecnología en Desarrollo de Software requieres: 1) Haber aprobado como mínimo el 70% del total de créditos del plan de estudios. 2) Estar a paz y salvo académico y financiero. 3) Modalidades autorizadas: Contrato de Aprendizaje SENA, Convenio de Pasantía, o Validación de Experiencia Laboral vigente (mínimo 6 meses en desarrollo de software). 4) Radicar la Carta de Solicitud y ARL de la empresa ante la coordinación académica.', 'practica profesional, pasantia, contrato de aprendizaje, empresa, requisitos practica, 70 por ciento creditos', 'coordinacion.software@teinco.edu.co', '+57 601 7433200', 'Sede Principal Calle 57 No. 9-28, Bloque B, Piso 2', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m. | Sábados: 7:00 a.m. a 2:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Coordinación Académica', 'Opciones de Grado', 'Opciones de Grado para Tecnología en Desarrollo de Software', 'En tu último semestre puedes escoger entre: 1) Proyecto de Desarrollo e Implementación de Software (Creación de aplicativos funcionales reales como AsistIA). 2) Seminario / Diplomado de Profundización Tecnológica (aprobado con nota mínima de 3.5). 3) Monografía de Investigación Aplicada o participación en semillero de investigación TEINCO.', 'opciones de grado, proyecto de grado, monografia, seminario de grado, diplomado, desarrollo de software', 'coordinacion.software@teinco.edu.co', '+57 601 7433200', 'Sede Principal Calle 57 No. 9-28, Bloque B, Piso 2', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m. | Sábados: 7:00 a.m. a 2:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Coordinación Académica', 'Evaluaciones y Supletorios', 'Exámenes Supletorios y Habilitaciones Académicas', 'Según el Reglamento Estudiantil: • Supletorio: Procede por inasistencia justificada a parciales o finales (incapacidad médica o fuerza mayor). Se solicita dentro de los 3 días hábiles siguientes al examen ante la coordinación cancelando los derechos respectivos. • Habilitación: Aplica para asignaturas teóricas reprobadas con calificación definitiva entre 2.0 y 2.9 (escala 0.0 a 5.0). La nota aprobatoria mínima es 3.0.', 'supletorio, habilitacion, examen supletorio, perder materia, incapacidad medica, nota minima', 'coordinacion.software@teinco.edu.co', '+57 601 7433200', 'Sede Principal Calle 57 No. 9-28, Bloque B, Piso 2', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m. | Sábados: 7:00 a.m. a 2:00 p.m.');
INSERT INTO knowledge_articles (division, category, title, content, keywords, contact_email, contact_phone, office_location, schedule) VALUES ('Soporte y Sistemas', 'Plataformas y Accesos', 'Acceso al Campus Virtual Moodle y Correo Institucional TEINCO', 'Para ingresar al Campus Virtual y herramientas tecnológicas: 1) Correo Institucional: usuario@teinco.edu.co con servicios de Google Workspace y Microsoft 365 Educación. 2) Campus Virtual Moodle: Acceso a aulas virtuales, foros y entrega de evidencias de aprendizaje. 3) Portal Académico Q10: Consulta de notas definitivas, asistencias y horarios. En caso de olvido de contraseña o bloqueo, escribe a soporte.sistemas@teinco.edu.co adjuntando tu documento de identidad.', 'clave, contraseña, correo institucional, moodle, campus virtual, q10, aulas virtuales, bloqueo', 'soporte.sistemas@teinco.edu.co', '+57 601 7433200 | WhatsApp: 301 333 7956', 'Sede Principal Calle 57 No. 9-28, Piso 4', 'Lunes a Viernes: 7:00 a.m. a 10:00 p.m. | Soporte virtual 24/7');